  ui_story_32230401_63_dialog_content = "Mira esto. ¡Así es como se ve la escama de una verdadera Doncella Dragón!",
  ui_story_32230401_64_dialog_content = "Cuando el abuelo del emperador actual aún ocupaba el trono, una vez salvó a la Doncella Dragón de un pulpo gigante en un viaje...",
  ui_story_32230401_65_dialog_content = "¿Ah?",
