  ui_story_32230401_68_dialog_content = "¿Qué te parece? Puedo rebajar el 1% del precio si realmente lo quieres.",
  ui_story_32230401_69_dialog_content = "(Estoy demasiado asustado para ver siquiera cómo Chen'ni está reaccionando a todo esto...)",
