  ui_story_32230401_71_dialog_content = "Todavía estaba echando una siesta en el fondo del mar cuando ese abuelo emperador gobernaba.",
  ui_story_32230401_72_dialog_content = "Veo que te consideras la Doncella del Dragón. ¿No estás delirando, pequeña niña?",
  ui_story_32230401_73_dialog_content = "Por favor detente, te lo ruego...",
  ui_story_32230401_74_dialog_content = "¿Me estás diciendo que pare cuando estás intentando engañarme, el principal experto en Longzhou aquí?",
  ui_story_32230401_75_dialog_content = "¿Ves esto? Esta es la auténtica sangre de dragón.",
  ui_story_32230401_76_dialog_content = "¿No es simplemente bronce?",
