  ui_story_32230401_78_dialog_content = "¡...!",
  ui_story_32230401_79_dialog_content = "Para crear la armadura más dura del mundo, rezaron a la Doncella Dragón.",
  ui_story_32230401_80_dialog_content = "Y para responder a sus oraciones, la Doncella Dragón dejó caer algo de su propia sangre en la forja.",
  ui_story_32230401_81_dialog_content = "Después de miles de años, la tribu se ha ido hace mucho tiempo, pero esta última armadura inexpugnable en el mundo...",
  ui_story_32230401_82_dialog_content = "¡Es la única prueba de que la Tribu del Telar alguna vez existió!",
  ui_story_32230401_83_dialog_content = "¡Impresionante, verdad? ¡Nadie ha visto un tesoro como este antes!",
  ui_story_32230401_84_dialog_content = "Estoy de acuerdo. Esta es la primera vez incluso para mí.",
  ui_story_32230401_85_dialog_content = "Je... ¡Jajajajaja!",
  ui_story_32230401_86_dialog_content = "¡Mocosos insolentes! ¿Cómo se atreven a burlarse de mí mientras intentan engañarme?",
  ui_story_32230401_87_dialog_content = "¡Lárgate, lárgate ahora! ¡Y llévate tu falsificación contigo!",
  ui_story_32230401_88_dialog_content = "El tendero ve la mancha de sangre cuando alcanza la báscula. Se detiene, frunce el ceño y la recoge con un trapo antes de tirarla.",
  ui_story_32230401_89_dialog_content = "¡Largo!",
  ui_story_32230401_90_dialog_content = "Ding dong!",
  ui_story_32230401_91_dialog_content = "¡Jajaja!",
  ui_story_32230401_92_dialog_content = "Vaya, lo siento, eso no es gracioso... ¡Pero realmente se lo diste!",
  ui_story_32230401_93_dialog_content = "No quería avergonzarlo, ya que sé cuán poco saben las personas aquí sobre los dragones en Longzhou.",
  ui_story_32230401_94_dialog_content = "Hasta que mencionó la Tribu Loom...",
  ui_story_32230401_95_dialog_content = "Bueno, ¿por qué no guardamos esa preciosa báscula tuya...",
  ui_story_32230401_96_dialog_content = "Espera, el trapo con el que el chico tiró la báscula...",
  ui_story_32230401_97_dialog_content = "¿Qué pasa? Lo agarró al azar de esos juguetes.",
  ui_story_32230401_98_dialog_content = "Supongo que era solo algún tipo de embalaje.",
  ui_story_32230401_99_dialog_content = "Sin arrugas cuando lo frotas, la artesanía única, el material resistente pero suave...",
  ui_story_32230401_100_dialog_content = "Esta es una reliquia de la Tribu Loom.",
  ui_story_32230401_101_dialog_content = "¿La tribu antigua? ¿Entonces el tendero no estaba mintiendo?",
  ui_story_32230401_102_dialog_content = "¿Qué tal si usamos tu sangre para hacer la armadura?",
  ui_story_32230401_103_dialog_content = "Eso es una mentira.",
  ui_story_32230401_104_dialog_content = "Vi lo absortos que estaban en el tejido y me interesé, lo suficiente como para protegerlos de los desastres por un tiempo.",
  ui_story_32230401_105_dialog_content = "Durante esos días de paz, desarrollaron rápidamente las mejores técnicas de tejido del mundo.",
