  ui_story_32230401_117_dialog_content = "...",
  ui_story_32230401_118_dialog_content = "(¡Así es como se ven los dragones cuando están enojados! Aprendí algo nuevo hoy.)",
  ui_story_32230401_119_dialog_content = "...",
  ui_story_32230401_120_dialog_content = "¡Muy bien, hora de la próxima tienda!",
  ui_story_32230401_121_dialog_content = "¿Qué estamos haciendo?",
  ui_story_32230401_122_dialog_content = "¡Vende mi escala para el modelo, por supuesto!",
  ui_story_32230401_123_dialog_content = "¿Todavía vas a seguir con eso?",
  ui_story_32230601_1_dialog_content = "¡Artemisa! ¡Cálamo! También vendo gardenias—",
  ui_story_32230601_2_dialog_content = "¡Se vende arroz de sorgo fresco! ¡No se puede hacer zongzi sin él!",
  ui_story_32230601_3_dialog_content = "Sé que hoy es el Festival de Colores de Longzhou, pero no esperaba que fuera tan animado.",
  ui_story_32230601_4_dialog_content = "¡Deléitense, todos! Mis prendas vienen desde el oeste, ¡un espectáculo raro de verdad!",
  ui_story_32230601_5_dialog_content = "Incluso venden ropa de Astra aquí.",
  ui_story_32230601_6_dialog_content = "¡Aja! ¡Veo que eres un verdadero conocedor! ¡Ven a echar un vistazo, amigo!",
  ui_story_32230601_7_dialog_content = "Estas ropas son de Astra, pero también tienen mucho del encanto de Longzhou. Estas deben haber venido de Twin Pavilions Bay.",
  ui_story_32230601_8_dialog_content = "Es interesante verlos a todos en este lado del océano.",
  ui_story_32230601_9_dialog_content = "Estas prendas fueron cuidadosamente seleccionadas por el Gremio Lin. Cada pieza es completamente única en su tipo.",
  ui_story_32230601_10_dialog_content = "Hacen los regalos perfectos para las señoras en tu vida.",
  ui_story_32230601_11_dialog_content = "¡Y con el Festival de Colores a la vuelta de la esquina, todos quieren lucir lo mejor posible con ropa completamente nueva!",
  ui_story_32230601_12_dialog_content = "No puedes dejar que las otras chicas eclipsen a la tuya, ¿verdad?",
  ui_story_32230601_13_dialog_content = "¿Esa también es otra tradición del festival?",
  ui_story_32230601_14_dialog_content = "(Ahora que lo pienso, Chen'ni siempre lleva el mismo atuendo. Me pregunto...)",
  ui_story_32230601_15_dialog_content = "Veo que lo estás pensando seriamente. Como muestra de mi sinceridad, te ofreceré el precio más bajo de la zona...",
  ui_story_32230601_16_dialog_content = "<color=#e8d9bb>Momentos después</color>",
  ui_story_32230601_17_dialog_content = "...",
  ui_story_32230601_18_dialog_content = "(¡Lo compré antes de darme cuenta! Los comerciantes del Reino Ji realmente son algo especial...)",
  ui_story_32230601_19_dialog_content = "Vaya, supongo que ya pagué por ello...",
  ui_story_32230601_20_dialog_content = "¿Pagado por qué?",
  ui_story_32230601_21_dialog_content = "¡Ah! ¿Chen'ni?",
  ui_story_32230601_22_dialog_content = "Eh, escuché que a las chicas les gusta usar atuendos nuevos durante el Festival de Colores. ¿Tú—",
  ui_story_32230601_23_dialog_content = "¡Sí, yo también!",
  ui_story_32230601_24_dialog_content = "¿Ah?",
  ui_story_32230601_25_dialog_content = "¿No te lo he dicho antes? Mi ropa también es una manifestación de mis poderos.",
  ui_story_32230601_26_dialog_content = "Están hechos de escamas de dragón, lo que significa que son impermeables al fuego, al agua y a la influencia de los espíritus malignos. ¡También puedo cambiar su apariencia, por supuesto!",
  ui_story_32230601_27_dialog_content = "¿En qué tipo de atuendo debería cambiarme, PlayerName? ¿Quizás uno de los vestidos de tu tierra natal?",
  ui_story_32230601_28_dialog_content = "(¡Así que no tenía sentido comprar esto después de todo!)",
  ui_story_32230601_29_dialog_content = "Jajaja... Claro, eso suena bien.",
  ui_story_32230601_30_dialog_content = "?",
  ui_story_32230601_31_dialog_content = "Entonces... ¿Qué compraste hace un momento de todos modos?",
  ui_story_32230601_32_dialog_content = "(¡No puedo hacerlo! ¡No puedo dárselo ahora!)",
  ui_story_32230601_33_dialog_content = "¡N-Nada! Solo me sorprendió encontrar tantos productos de Astra por aquí, eso es todo.",
  ui_story_32230601_34_dialog_content = "¡Mira allá!",
  ui_story_32230601_35_dialog_content = "¡Delicias y adornos occidentales! ¡No pierdas la oportunidad de comprarlos!",
  ui_story_32230601_36_dialog_content = "¡Esos se ven deliciosos! ¡Tomaré algunos!",
  ui_story_32230601_37_dialog_content = "(Uf... Solo guardaré estos por ahora.)",
  ui_story_32230601_38_dialog_content = "El empaque de este bocadillo parece muy apretado y no puedo entender nada de lo que está escrito en él. ¡Supongo que lo mejor será probarlo primero!",
  ui_story_32230601_39_dialog_content = "Espera Chen'ni, eso es—",
  ui_story_32230601_40_dialog_content = "*mascas*",
  ui_story_32230601_41_dialog_content = "Una galleta militar súper comprimida de la Federación Illumina. Se supone que debes agregarle agua...",
  ui_story_32230601_42_dialog_content = "*traga* ¿Mmm?",
  ui_story_32230601_43_dialog_content = "E-El galleta se está expandiendo en mi boca!",
  ui_story_32230601_44_dialog_content = "Mantén la calma, Chen'ni! ¡Solo escúpelo!",
  ui_story_32230601_45_dialog_content = "¡Está tan seco! ¡La galleta está absorbiendo toda la humedad de mi cuerpo!",
  ui_story_32230601_46_dialog_content = "Agua... ¡Necesito agua!",
  ui_story_32230601_47_dialog_content = "¡Hay un río por ahí!",
  ui_story_32230601_48_dialog_content = "<color=#e8d9bb>¡Chapoteo!</color>",
  ui_story_32230601_49_dialog_content = "... Chen'ni?",
  ui_story_32230601_50_dialog_content = "¡Ja! ¡Qué bocadillo tan interesante!",
  ui_story_32230601_51_dialog_content = "Me alegro que te haya gustado, supongo... Aquí, toma mi mano antes de que te marees por nadar después de comer.",
  ui_story_32230601_52_dialog_content = "Ah, mi ropa está toda empapada.",
  ui_story_32230601_53_dialog_content = "¿Eh? Pero acabas de decir que tu ropa era impermeable a—",
  ui_story_32230601_54_dialog_content = "Oh querido, ¿qué haré ahora? Esto es bastante enigmático.",
  ui_story_32230601_55_dialog_content = "Solo usa tus poderes—",
  ui_story_32230601_56_dialog_content = "Me pregunto dónde podría encontrar un conjunto de ropa fresco?",
  ui_story_32230601_57_dialog_content = "*observa*",
  ui_story_32230601_58_dialog_content = "Bueno, si vas a mirar así... Aquí tienes.",
  ui_story_32230601_59_dialog_content = "A veces pienso que podrías ser mejor leyendo mentes que un Caelestite, Chen'ni.",
  ui_story_32230601_60_dialog_content = "¡No tengo idea de lo que estás hablando!",
  ui_story_32230601_61_dialog_content = "Incluso un dragón como yo olvida cómo mantener su magia de vez en cuando.",
  ui_story_32230601_62_dialog_content = "Sí, claro, lo que tú digas. Solo sube aquí, ¿podrías?",
  ui_story_32230601_63_dialog_content = "Resulta que tengo un vestido solo para ti.",
  ui_story_32230601_64_dialog_content = "Vaya, PlayerName!",
  ui_story_32230601_65_dialog_content = "¡Este vestido es tan lindo! ¡Lo amo!",
  ui_story_32230601_66_dialog_content = "¡He querido probarme la ropa de Astra desde hace mucho tiempo!",
  ui_story_32230601_67_dialog_content = "Me alegra que te guste.",
  ui_story_32230601_68_dialog_content = "He querido preguntar, pero ¿qué estás haciendo aquí de todos modos?",
  ui_story_32230601_69_dialog_content = "Oh, bueno...",
  ui_story_32230601_70_dialog_content = "De hecho, estoy buscando un deseo.",
  ui_story_32230601_71_dialog_content = "¿Un deseo?",
  ui_story_32230601_72_dialog_content = "¡Siempre que alguien me ora y me envía una ofrenda, puedo escuchar los deseos más profundos de su corazón!",
  ui_story_32230601_73_dialog_content = "Después de todo, vivir en el reino mortal es tener deseos.",
  ui_story_32230601_74_dialog_content = "Algunos anhelan riqueza, autoridad, amor o un lugar al que llamar hogar. Otros simplemente desean que las cosas vayan a su manera.",
  ui_story_32230601_75_dialog_content = "Pero este deseo es diferente a lo habitual.",
  ui_story_32230601_76_dialog_content = "Todo lo que sé es que alguien me hizo una ofrenda, pero por alguna razón, no pude escuchar su deseo claramente.",
  ui_story_32230601_77_dialog_content = "¡No tuve más opción que aparecer y averiguar por qué este deseo era tan difícil de entender!",
  ui_story_32230601_78_dialog_content = "Entiendo, así que viniste al festival buscando a alguien.",
  ui_story_32230601_79_dialog_content = "Permíteme ayudarte entonces. Tal vez mi habilidad psíquica pueda ser útil aquí.",
  ui_story_32230601_80_dialog_content = "PlayerName...",
  ui_story_32230601_81_dialog_content = "¿Qué es?",
  ui_story_32230601_82_dialog_content = "Nada. ¿Por qué no intentas usar tus poderes en mí?",
  ui_story_32230601_83_dialog_content = "De esa manera, puedo compartir lo que escucho contigo.",
  ui_story_32230601_84_option_content = "¡Potencia de fuerza!",
  ui_story_32230601_85_dialog_content = "Doncella del Dragón, escucha mi súplica, deseo ser promovido este año y hacer fortuna.",
  ui_story_32230601_86_dialog_content = "¡Todopoderosa Divinidad del Dragón Benevolente! ¡Por favor, protégeme en este viaje!",
  ui_story_32230601_87_dialog_content = "Oh poderosa Doncella Dragón, ¿alguna vez encontraré al hombre de mis sueños?",
  ui_story_32230601_88_dialog_content = "Urgh...",
  ui_story_32230601_89_dialog_content = "¿Estás bien?",
  ui_story_32230601_90_dialog_content = "Sí, solo un poco mareado por todas esas voces en tu mente justo ahora.",
  ui_story_32230601_91_dialog_content = "¿Es esto lo que tienes que escuchar cada segundo de todos los días?",
  ui_story_32230601_92_dialog_content = "Así es. Soy una diosa, ¿recuerdas?",
  ui_story_32230601_93_dialog_content = "Vaya, sigo perdiendo en las batallas de césped. ¿Podrías ayudarme, Doncella del Dragón?",
  ui_story_32230601_94_dialog_content = "¿L-La gente realmente desea cosas así? ¿Eh? ¿Dónde fue Chen'ni?",
  ui_story_32230601_95_dialog_content = "¡Este juego parece muy divertido! ¿Cómo se juega?",
  ui_story_32230601_96_dialog_content = "Se llama batalla en la hierba, querido.",
  ui_story_32230601_97_dialog_content = "Primero, tenemos que encontrar dos tallos de hierba largos. Luego los cruzamos y tiramos, y quien rompa el tallo del otro gana.",
  ui_story_32230601_98_dialog_content = "Si ganas tres veces seguidas, obtienes esta bonita horquilla.",
  ui_story_32230601_99_dialog_content = "(Mi mami está demasiado enferma para salir de casa. Quiero animarla ganando esto por ella, pero solo sigo perdiendo...)",
  ui_story_32230601_100_dialog_content = "¡Quiero jugar!",
  ui_story_32230601_101_dialog_content = "¿Ahora mismo? Claro, pero ¿dónde se supone que encontraremos hierba para el juego?",
  ui_story_32230601_102_dialog_content = "<color=#e8d9bb>Sin un momento de vacilación, Chen'ni arranca un solo pelo de su cola.</color>",
  ui_story_32230601_103_dialog_content = "¡Usa esto!",
  ui_story_32230601_104_dialog_content = "¡Oye!",
  ui_story_32230601_105_dialog_content = "(¡Pero eso sería hacer trampa!)",
  ui_story_32230601_106_dialog_content = "(No te preocupes, usaré mis poderes para asegurarme de que nadie se dé cuenta.)",
  ui_story_32230601_107_dialog_content = "(Oh, ¿así que ahora puedes usar tu magia?)",
  ui_story_32230601_108_dialog_content = "<color=#e8d9bb>Tres partidos después</color>",
  ui_story_32230601_109_dialog_content = "¡Gano!",
  ui_story_32230601_110_dialog_content = "¡Apenas puedo creerlo! He estado jugando todo el día, pero eres la primera persona que me vence.",
  ui_story_32230601_111_dialog_content = "Aquí, esta horquilla es tuya ahora.",
  ui_story_32230601_112_dialog_content = "Mira, PlayerName! ¡Gané!",
  ui_story_32230601_113_dialog_content = "¡Vaya, eso es increíble!",
  ui_story_32230601_114_dialog_content = "(Aunque definitivamente hiciste trampa...)",
  ui_story_32230601_115_dialog_content = "Las batallas en la hierba son muy divertidas, pero realmente no necesito esta horquilla.",
  ui_story_32230601_116_dialog_content = "¡Supongo que simplemente tendré que deshacerme de él!",
  ui_story_32230601_117_dialog_content = "<color=#e8d9bb>Chen'ni lanza la horquilla al aire, donde gira dos veces antes de aterrizar suavemente en las manos de la pequeña niña.</color>",
  ui_story_32230601_118_dialog_content = "¡Es la Doncella Dragón! ¡Ella realmente está aquí!",
  ui_story_32230601_119_dialog_content = "Deja de quedarte parado, PlayerName! ¡Todavía hay muchas cosas divertidas por hacer!",
  ui_story_32230601_120_dialog_content = "Estaré ahí—¿eh?",
  ui_story_32230601_121_dialog_content = "Tan dulce... Tengo tanta hambre.",
  ui_story_32230601_122_dialog_content = "Esta voz... ¿También cuenta como un deseo?",
  ui_story_32230601_123_dialog_content = "¡Acércate al concurso de envoltura de zongzi más grande del Festival de Colores! ¡Inscríbete con un amigo antes de que comience la próxima ronda!",
  ui_story_32230601_124_dialog_content = "¡PlayerName!",
  ui_story_32230601_125_dialog_content = "Déjame adivinar, quieres registrarte, ¿verdad?",
  ui_story_32230601_126_dialog_content = "¡Sí!",
  ui_story_32230601_127_dialog_content = "Las reglas son simples: ¡el equipo que envuelva más zongzi antes de que este palo de incienso se consuma gana un fabuloso premio!",
  ui_story_32230601_128_dialog_content = "¡Y comenzar!",
  ui_story_32230601_129_dialog_content = "Sé que es un poco raro de mi parte decir esto ahora.",
  ui_story_32230601_130_dialog_content = "Pero Chen'ni...",
  ui_story_32230601_131_dialog_content = "¿Sabes siquiera cómo envolver este \"zongzi\"?",
  ui_story_32230601_132_dialog_content = "Para nada.",
  ui_story_32230601_133_dialog_content = "Yo tampoco.",
  ui_story_32230601_134_dialog_content = "¿M-Tal vez deberíamos ver cómo lo hacen otras personas primero?",
  ui_story_32230601_135_dialog_content = "...",
  ui_story_32230601_136_dialog_content = "Es sorprendentemente simple de hacer. ¡Creo que lo tenemos!",
  ui_story_32230601_137_dialog_content = "¡El concurso está ahora a mitad de camino! ¡Sigamos animando a nuestros equipos!",
  ui_story_32230601_138_dialog_content = "Se está volviendo cada vez más fácil envolver estos. ¡Creo que tenemos una verdadera oportunidad de ganar ahora! ¿Cuántos tenemos—",
  ui_story_32230601_139_dialog_content = "Uh, ¿dónde están todos los zongzi que acabo de envolver?",
  ui_story_32230601_140_dialog_content = "¡Eructo!",
  ui_story_32230601_141_dialog_content = "...¡No! ¡Escúpelo ahora mismo! ¡Todavía están crudos!",
  ui_story_32230601_142_dialog_content = "<color=#e8d9bb>Momentos después</color>",
  ui_story_32230601_143_dialog_content = "¡Se acabó el tiempo! ¡El concurso ha terminado!",
  ui_story_32230601_144_dialog_content = "¡Eso fue rápido!",
  ui_story_32230601_145_dialog_content = "Al final, solo tuvimos suficiente tiempo para envolver un solo zongzi.",
  ui_story_32230601_146_dialog_content = "No ganamos nada, pero el dueño del puesto tuvo la amabilidad de cocinarlo para nosotros. También huele bastante sabroso.",
  ui_story_32230601_147_dialog_content = "Chirrido...",
  ui_story_32230601_148_dialog_content = "¿Eh? ¿Fue tu voz la que escuché antes?",
  ui_story_32230601_149_dialog_content = "Aquí, toma este zongzi. El relleno es de dátiles rojos, así que es agradable y dulce.",
  ui_story_32230601_150_dialog_content = "¡Chirrido!",
  ui_story_32230601_151_dialog_content = "<color=#e8d9bb>El pequeño Fiundling salta y besa a PlayerName en la mano antes de alejarse felizmente con su zongzi.</color>",
  ui_story_32230601_152_dialog_content = "Esa cosita realmente te quiere, PlayerName.",
  ui_story_32230601_153_dialog_content = "... Es gracioso.",
  ui_story_32230601_154_dialog_content = "Aunque no ganamos nada, aún me siento realmente feliz.",
  ui_story_32230601_155_dialog_content = "¿Es esto lo que sueles hacer? ¿Escuchar los corazones de los demás y conceder sus deseos?",
  ui_story_32230601_156_dialog_content = "Para una diosa como tú, no podemos ser más que visitantes fugaces en tu vida.",
  ui_story_32230601_157_dialog_content = "¿Qué tiene eso que ver con nada? Estás feliz en este momento, ¿no?",
  ui_story_32230601_158_dialog_content = "¡Yo también!",
  ui_story_32230601_159_dialog_content = "En mis ojos, vuestras vidas son indudablemente cortas.",
  ui_story_32230601_160_dialog_content = "Pero es posible que mi vida sea igual de efímera en el gran esquema de la existencia.",
  ui_story_32230601_161_dialog_content = "En ese sentido, todos somos iguales, aurorianos, diablillos y nosotros dos también.",
  ui_story_32230601_162_dialog_content = "Estamos limitados en nuestra existencia, sí.",
  ui_story_32230601_163_dialog_content = "Pero aquí y ahora, estamos disfrutando de los mismos momentos fugaces juntos, ¿no es así?",
  ui_story_32230601_164_dialog_content = "Es natural querer hacer estos momentos lo más alegres posible.",
  ui_story_32230601_165_dialog_content = "¡Así que vamos! Tengo la sensación de que todavía tenemos muchos momentos felices para disfrutar!",
  ui_story_32230601_166_dialog_content = "¡Seguro!",
  ui_story_32230601_167_dialog_content = "Bueno, lo que dijiste puede ser cierto...",
  ui_story_32230601_168_dialog_content = "Pero Chen'ni... ¿Crees que podríamos tomar un descanso primero?",
  ui_story_32230601_169_dialog_content = "¿Ya estás cansado, PlayerName?",
  ui_story_32230601_170_dialog_content = "¡Bueno, sí! Tuvimos batallas de hierba, envolvimos zongzi, recolectamos hierbas y ayudamos a un herrero en su fragua...",
  ui_story_32230601_171_dialog_content = "¡Incluso participamos en tres carreras de botes de dragón como sustitutos de última hora!",
  ui_story_32230601_172_dialog_content = "¡Sería raro si no estuviera cansado!",
  ui_story_32230601_173_dialog_content = "Está bien, aquí tienes un pedazo de pastel de arroz para ayudarte a recuperar tus fuerzas.",
  ui_story_32230601_174_dialog_content = "Gracias... Pero, ¿de dónde has sacado esto?",
  ui_story_32230601_175_dialog_content = "¡De una ofrenda!",
  ui_story_32230601_176_dialog_content = "¿Ves? Hay un santuario dedicado a mí justo adelante.",
  ui_story_32230601_177_dialog_content = "¿Incluso aquí, eh? Todos deben respetarte mucho, Chen'ni.",
  ui_story_32230601_178_dialog_content = "¿Eh? Es eso...",
  ui_story_32230601_179_dialog_content = "Muchas gracias, Doncella del Dragón. A mi mamá le encantó mucho su regalo.",
  ui_story_32230601_180_dialog_content = "Te alabo, mi diosa, mi negocio fue especialmente bien hoy.",
  ui_story_32230601_181_dialog_content = "¡Chirrido!",
  ui_story_32230601_182_dialog_content = "<color=#e8d9bb>Uno a uno, la gente deja todo tipo de ofrendas en el santuario. Incluso ese pequeño Fiundling deja una flor silvestre junto al santuario.</color>",
  ui_story_32230601_183_dialog_content = "¿Por qué también dejaron todos este hilo atrás?",
  ui_story_32230601_184_dialog_content = "Durante el Festival de Colores, es costumbre que las personas se envíen hilos coloridos como regalos.",
  ui_story_32230601_185_dialog_content = "Cada uno de los cinco colores representa un significado o deseo diferente.",
  ui_story_32230601_186_dialog_content = "Al trenzar los cinco colores en una pulsera y usarlos, las personas pueden mejorar su suerte y evitar desastres.",
  ui_story_32230601_187_dialog_content = "Ofrecerme estos hilos también es su forma de expresar gratitud.",
  ui_story_32230601_188_dialog_content = "Desafortunadamente, solo veo cuatro colores aquí, no cinco.",
  ui_story_32230601_189_dialog_content = "Pero nada es perfecto nunca, ¿verdad?",
  ui_story_32230601_190_dialog_content = "Al igual que hoy nos divertimos mucho a pesar de no encontrar a la persona que hizo ese extraño deseo.",
  ui_story_32230601_191_dialog_content = "No, definitivamente lo encontré hace mucho tiempo.",
  ui_story_32230601_192_dialog_content = "¿En serio? ¿Cuándo pasó eso?",
  ui_story_32230601_193_dialog_content = "Justo cuando conseguí este vestido, en realidad.",
  ui_story_32230601_194_dialog_content = "Esa voz era tuya, PlayerName.",
  ui_story_32230601_195_dialog_content = "?",
  ui_story_32230601_196_dialog_content = "Tu ofrenda me agradó mucho. Habla tu deseo, y yo lo concederé para ti.",
  ui_story_32230601_197_option_content = "Bueno, sí tengo un deseo.",
  ui_story_32230601_198_dialog_content = "Entonces nombra tu ambición o el objeto que deseas, y yo lo haré tuyo.",
  ui_story_32230601_199_dialog_content = "No estoy interesado en nada de eso.",
  ui_story_32230601_200_option_content = "No tengo un deseo.",
  ui_story_32230601_201_dialog_content = "¿Por qué?",
  ui_story_32230601_202_dialog_content = "Porque ese vestido no era una ofrenda, ni mi forma de pedir un deseo.",
  ui_story_32230601_203_dialog_content = "Solo quería darte un regalo, Chen'ni.",
  ui_story_32230601_204_dialog_content = "Si tuviera que adjuntar un deseo a ello...",
  ui_story_32230601_205_dialog_content = "Entonces definitivamente sería por tu bien.",
  ui_story_32230601_206_dialog_content = "Todopoderosa Divinidad del Dragón Benevolente, escucha mi súplica—",
  ui_story_32230601_207_dialog_content = "¡Mi deseo es que siempre seas tan feliz!",
  ui_story_32230601_208_dialog_content = "Después de todos estos años, he perdido la cuenta de cuántas personas hicieron deseos para que yo los cumpliera. ¿Por qué harías un deseo por mi bien?",
  ui_story_32230601_209_dialog_content = "Incluso si hicieras un deseo bastante egoísta, no me importaría concederlo.",
  ui_story_32230601_210_dialog_content = "¿Estás seguro de que no te arrepentirás de desperdiciar una oportunidad tan rara?",
  ui_story_32230601_211_dialog_content = "Por supuesto que no.",
  ui_story_32230601_212_dialog_content = "Los regalos están destinados a hacer felices a las personas, y eso es todo.",
  ui_story_32230601_213_dialog_content = "Ya que lo llamas un regalo...",
  ui_story_32230601_214_dialog_content = "Es apropiado que te dé algo a cambio.",
  ui_story_32230601_215_dialog_content = "Oh, no te preocupes por eso. Solo lo compré por capricho—",
  ui_story_32230601_216_dialog_content = "Extiende tu mano, PlayerName.",
  ui_story_32230601_217_dialog_content = "<color=#e8d9bb>De repente, el viento a su alrededor se detiene por completo.</color>",
  ui_story_32230601_218_dialog_content = "<color=#e8d9bb>Con un gesto, Chen'ni convoca un hilo verde de su santuario, que flota y rodea la muñeca de PlayerName.</color>",
  ui_story_32230601_219_dialog_content = "Un hilo de verde para representar el bosque, el este y la primavera que da vida.",
  ui_story_32230601_220_dialog_content = "May que los vientos de la primavera te traigan salud y felicidad.",
  ui_story_32230601_221_dialog_content = "<color=#e8d9bb>Un hilo rojo flota sobre y se teje alrededor del hilo verde.</color>",
  ui_story_32230601_222_dialog_content = "Un hilo de rojo para representar el fuego, el sur y el floreciente verano.",
  ui_story_32230601_223_dialog_content = "May el calor del verano te brinde fuerza y valor.",
  ui_story_32230601_224_dialog_content = "<color=#e8d9bb>Un hilo blanco se desliza y se entrelaza con los otros dos.</color>",
  ui_story_32230601_225_dialog_content = "Un hilo de blanco para representar el trueno, el oeste y el otoño abundante.",
  ui_story_32230601_226_dialog_content = "May la cosecha de otoño te traiga éxito en todos tus esfuerzos.",
  ui_story_32230601_227_dialog_content = "<color=#e8d9bb>Un hilo negro se desliza y se añade ágilmente a la pulsera.</color>",
  ui_story_32230601_228_dialog_content = "Un hilo de negro para representar el agua, el norte y el inevitable invierno.",
  ui_story_32230601_229_dialog_content = "May las tormentas de invierno te traigan nueva vida e iluminación.",
  ui_story_32230601_230_dialog_content = "<color=#e8d9bb>Con eso, todos los hilos en el santuario se han agotado.</color>",
  ui_story_32230601_231_dialog_content = "Incluso con solo cuatro colores, esta pulsera es absolutamente hermosa. ¡Me encanta!",
  ui_story_32230601_232_dialog_content = "Eso es genial y todo, pero ¿qué tipo de amigo sería si te diera un regalo sin terminar? ¡Mira esto!",
  ui_story_32230601_233_dialog_content = "<color=#e8d9bb>Chen'ni levanta su mano y junta sus dedos. Su energía divina surge y forma un hilo dorado en el aire.</color>",
  ui_story_32230601_234_dialog_content = "Un hilo de oro para representar el centro, el dragón, y...",
  ui_story_32230601_235_dialog_content = "¡Yo!",
  ui_story_32230601_236_dialog_content = "¿Ah?",
  ui_story_32230601_237_dialog_content = "<color=#e8d9bb>Si levantas la cara ahora mismo, verás sus ojos brillando de alegría.</color>",
  ui_story_32230601_238_dialog_content = "Solo diré esto una vez, PlayerName—",
  ui_story_32230601_239_dialog_content = "Por favor, mantente saludable y vive una vida más larga.",
  ui_story_32230601_240_dialog_content = "De esta manera, podemos compartir aún más momentos felices juntos.",
  ui_story_32230601_241_dialog_content = "Aunque probablemente no sea nada comparado con tu esperanza de vida...",
  ui_story_32230601_242_dialog_content = "Haré lo mejor que pueda para seguir adelante.",
  ui_story_32230601_243_dialog_content = "Esto no debería ser muy difícil, ya que te tengo cuidándome.",
  ui_story_32230601_244_dialog_content = "<color=#e8d9bb>Chen'ni ata cuidadosamente los dos extremos de la pulsera, el hilo dorado brilla intensamente entre los otros cuatro colores.</color>",
  ui_story_32230601_245_dialog_content = "May toda la belleza del mundo baile a tu nombre, y May tu sabio liderazgo florezca por mil años.",
  ui_story_32230601_246_dialog_content = "May todas las cosas en este mundo se prestan para la realización de tus deseos...",
  ui_story_32230601_247_dialog_content = "Por toda la eternidad."
}
return config
